    chapters = {
        {
            chapter = "The Fall of Sunnyglade",
            summaryAlliance = "Friz Frazzlespark at Powderfuse Port needs a crate carried inland to Knight Commander Demar Brant at Farholde Keep. The keep has bigger worries than goblin deliveries: the Twilight's Hammer has burned the village of Sunnyglade, and nobody knows why.",
            summaryHorde = "Friz Frazzlespark at Powderfuse Port needs a crate carried up to Krom'rosh at Rog'mar. The orcs there have fought Farholde's humans over the Riverglades for years, and now there's a third party: the Twilight's Hammer has burned the human village of Sunnyglade.",
            recapAlliance = "I delivered a goblin's crate to Farholde Keep and walked straight into somebody else's war. Farholde and the orcs of Rog'mar had been fighting over the Riverglades for years, and now the Twilight's Hammer had burned the village of Sunnyglade and moved into the ruins.\n\nI spent a while clearing them out and carrying their pages and charms back to the keep. That's not the part I remember.\n\nThe part I remember is Farmer Elbrim. The raiders had taken keepsakes off the farmers they killed. I took them back and laid them on the graves. Then Elbrim asked me to go into the barn where the family had hidden and bring out whatever was left.\n\nA doll and a locket. That was what was left.",
            recapHorde = "I carried a goblin's crate up to Rog'mar and found the orcs there with a new problem. They'd been fighting the humans of Farholde over the Riverglades for years, and now the Twilight's Hammer had burned the human village of Sunnyglade and settled into the ashes. Nobody had invited them.\n\nTran'gul wanted to know why they'd come. I brought back the shadowmancers' letters, Tran'gul read every word, and then wanted a miner, alive and talking.\n\nThe miner wasn't talking, at first. I can be very persuasive.\n\nBy the end of it Tran'gul was sure of one thing. The cult hadn't come to the Riverglades for a village. It had come to dig.",
            quests = {
                { id = 95059, name = "Frazzlespark's Crate", npc = "Friz Frazzlespark", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94877, name = "Saving Sunnyglade", npc = "Demar Brant", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94879, name = "Scraps of Knowledge", npc = "Ashe Amberhall", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94881, name = "Curious Trinkets", npc = "Ashe Amberhall", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94829, name = "What We Lost", npc = "Farmer Elbrim", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94858, name = "All That's Left", npc = "Farmer Elbrim", faction = "Alliance", gameVersions = { forever = true } },
                { id = 95062, name = "Frazzlespark's Crate", npc = "Friz Frazzlespark", faction = "Horde", gameVersions = { forever = true } },
                { id = 94672, name = "Encroaching Twilight", npc = "Tran'gul", faction = "Horde", gameVersions = { forever = true } },
                { id = 94680, name = "Twilight Missives", npc = "Tran'gul", faction = "Horde", gameVersions = { forever = true } },
                { id = 94727, name = "Digging for Answers", npc = "Tran'gul", faction = "Horde", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "Beneath Sunnyglade",
            summaryAlliance = "The Twilight's Hammer didn't burn Sunnyglade for the view. There are caves under the village, and the cult is busy in them. Apprentice Claire of Farholde Keep is already down there, and could use a hand.",
            summaryHorde = "Tran'gul is sure the Twilight's Hammer came to the Riverglades to dig, and the digging is under Sunnyglade. Down in the caves there, an ogre miner named Clubtoe has lost some friends and wants them found.",
            recapAlliance = "Under Sunnyglade the cult had caves, and in the caves it had ogres, and it was pouring void magic into them to see what happened. Mostly what happened was dead ogres. Now and then it was something a lot bigger and angrier.\n\nDown there I found Claire, an apprentice from Farholde Keep, trapped under the place Claire used to call home. Claire handed me a crystal catalyst to fill with the cult's magic, and I filled it, the hard way.\n\nThe one in charge down there was Chogg'Zac. Chogg'Zac had two heads. Claire wanted both. I brought back both.\n\nThen I carried the full catalyst up to Farholde and let the experts worry about what was in it.",
            recapHorde = "There's a cave under Sunnyglade, and down there I met Clubtoe. An ogre miner, looking for friends who'd gone missing. I helped look. What we found was the cult pouring void magic into ogres, making a few of them huge and wrong and killing a great many more.\n\nClubtoe took that about as well as you'd expect. We smashed their glowing circles and went for the one in charge, Chogg'Zac. One ogre, two heads.\n\nThat was it for Clubtoe and the Twilight's Hammer. Before heading off to join the ogres who'd already walked out on the cult, Clubtoe handed me one of the heads to carry home to Rog'mar.\n\nNice gesture. Heavy gesture.",
            quests = {
                { id = 95642, name = "Abominable Magics", npc = "Apprentice Claire", faction = "Alliance", gameVersions = { forever = true } },
                { id = 95643, name = "Indiscriminate Purge", npc = "Apprentice Claire", faction = "Alliance", gameVersions = { forever = true } },
                { id = 95562, name = "Cut Off the Heads", npc = "Apprentice Claire", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94884, name = "An Unsettling Discovery", npc = "Apprentice Claire", faction = "Alliance", gameVersions = { forever = true } },
                { id = 95417, name = "The Purple Ones", npc = "Clubtoe", faction = "Horde", gameVersions = { forever = true } },
                { id = 95601, name = "The Purple Ones", faction = "Horde", location = "the caves beneath Sunnyglade, Riverglades", gameVersions = { forever = true } },
                { id = 95602, name = "Sickening Lights", npc = "Clubtoe", faction = "Horde", gameVersions = { forever = true } },
                { id = 95427, name = "Twilight No More!", npc = "Clubtoe", faction = "Horde", gameVersions = { forever = true } },
                { id = 95418, name = "Spread the Word", npc = "Clubtoe", faction = "Horde", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "Land of Giants",
            faction = "Horde",
            summary = "Tran'gul has an ogre's head and a use for it. Carry it north to Bolder'ok, where the ogres who walked out on the Twilight's Hammer live by one rule: whoever hits hardest is right. Their leader, Clugfist, will take some convincing.",
            recap = "An ogre's head makes a fine introduction, so Tran'gul sent me north with one to Bolder'ok, where the ogres who quit the Twilight's Hammer live by one rule: whoever hits hardest is right.\n\nTheir leader, Clugfist, sized me up the only way an ogre knows. Smash the weaklings who crept back to the cult. Then get Clugfist's own weapon back off Klunk, the champion who ran off with it. I did both.\n\nClugfist allowed that the Horde might be stronger than expected. From an ogre, that's practically a love song.\n\nI carried the decree home: Bolder'ok and Rog'mar would be spilling blood together soon.",
            quests = {
                { id = 95420, name = "Land of Giants", npc = "Tran'gul", faction = "Horde", gameVersions = { forever = true } },
                { id = 95424, name = "Might Makes Right", npc = "Clugfist", faction = "Horde", gameVersions = { forever = true } },
                { id = 95425, name = "Unworthy Champion", npc = "Clugfist", faction = "Horde", gameVersions = { forever = true } },
                { id = 95428, name = "Clugfist's Decree", npc = "Clugfist", faction = "Horde", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "The Twilight's Shroud",
            summaryAlliance = "West of Sunnyglade the cult has raised a fortress, the Twilight's Shroud, and Sergeant Riftan of Farholde has been holding the line in front of it with no word from home. Knight Commander Demar Brant at Farholde Keep sends you to find the sergeant.",
            summaryHorde = "Da'grosh, one of Rog'mar's warriors, has gone west to take a swing at the cult's new fortress, the Twilight's Shroud. Krom'rosh would like to know how that's going. Find Da'grosh in the hills west of Rog'mar.",
            recapAlliance = "West of Sunnyglade the cult had built itself a fortress, the Twilight's Shroud, and a sergeant from Farholde had been holding the border in front of it with no word from home. Somebody had to turn up eventually. It was me.\n\nFive of Farholde's scouts were sitting in the cult's cages. I took keys off the cultists until I had enough and let them all out.\n\nThen I went looking for whoever was running the cult's whole campaign. Overlord Kilgar, deep in the Shroud. The sergeant asked for his head, so that's what I brought back.\n\nGood news for Farholde, for once.",
            recapHorde = "Da'grosh is the sort who doesn't wait for anybody. Da'grosh had charged the cult's new fortress, the Twilight's Shroud, and watched his warriors dragged off into cages. So we went back in, and I let five of Rog'mar's scouts out.\n\nThe better part was a cave nearby where the cult kept ogres digging for it. A Bolder'ok ogre and I talked five of those miners into turning on their masters. Their executioner didn't get talked into anything, so I took the executioner's mace home to Bolder'ok.\n\nLast came Overlord Kilgar, who ran the whole show. Da'grosh wanted his head. Da'grosh got it.",
            quests = {
                { id = 94886, name = "The Western Front", npc = "Demar Brant", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94888, name = "No Soldier Left Behind", npc = "Sergeant Riftan", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94889, name = "Carving a Path", npc = "Sergeant Riftan", faction = "Alliance", gameVersions = { forever = true } },
                { id = 96015, name = "A Miner Problem", npc = "Sergeant Riftan", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94890, name = "Bring Me His Head", npc = "Sergeant Riftan", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94891, name = "News to Farholde", npc = "Sergeant Riftan", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94744, name = "The Wayward Warrior", npc = "Krom'rosh", faction = "Horde", gameVersions = { forever = true } },
                { id = 94745, name = "Carving a Path", npc = "Da'grosh", faction = "Horde", gameVersions = { forever = true } },
                { id = 94748, name = "Break Their Chains", npc = "Da'grosh", faction = "Horde", gameVersions = { forever = true } },
                { id = 95431, name = "Rumblings of Discontent", faction = "Horde", location = "Riverglades", gameVersions = { forever = true } },
                { id = 95432, name = "Rise Up!", npc = "Crag'rog", faction = "Horde", gameVersions = { forever = true } },
                { id = 95433, name = "Death to the Executioner", faction = "Horde", location = "Riverglades", gameVersions = { forever = true } },
                { id = 94768, name = "Bring Me His Head", npc = "Da'grosh", faction = "Horde", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "Krol'dok Stronghold",
            summaryAlliance = "Overlord Kilgar is dead, and the Twilight's Hammer keeps coming anyway. Ashe Amberhall at Farholde Keep wants to know where from, and has a soulstone and an idea. All it needs is a small favor from you.",
            summaryHorde = "Overlord Kilgar is dead, and the Twilight's Hammer keeps coming anyway, out of Krol'dok, a stronghold hidden in the mountains. Getting in takes a key. A crude mould off one of its cultists is a start, if someone at Rog'mar can work with it.",
            recapAlliance = "Kilgar was dead and the cult kept coming anyway, which is the trouble with cults.\n\nAshe Amberhall at Farholde had an idea, and a soulstone. I called a thrall up out of one of the cult's conduits and caught it in the stone, and Ashe asked it questions until it gave up where they were coming from: a stronghold hidden in the mountains, Krol'dok.\n\nThe way in needed a key, and all we had was a crude mould. That got sorted. Inside, I made sure the stronghold had no leader anymore, and came home with the Eye of Mugg to prove it. It's the sort of proof nobody argues with.",
            recapHorde = "With Kilgar dead you'd think the cult would take the hint. It didn't. Their trail led to a stronghold hidden in the mountains, Krol'dok, and the only way in was a key nobody had. What we did have was a crude mould off a cultist, and Kreza Darkthorn at Rog'mar could work with that.\n\nInside, I collected a token of vengeance. Fifteen cultists' ears. I counted twice.\n\nI came out with their tome as well, and the Eye of Mugg, so Rog'mar could see for itself that the stronghold's leader wouldn't be leading anything anymore.",
            quests = {
                { id = 94907, name = "A Small Favor", npc = "Ashe Amberhall", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94980, name = "Krol'dok Moulding", hint = "That mould isn't natural. Someone in Farholde Keep might know what it is.", hintExplorer = "Someone in Farholde Keep may know more.", faction = "Alliance", location = "Krol'dok Stronghold, Riverglades", gameVersions = { forever = true } },
                { id = 94981, name = "Key Ingredients", npc = "Alphonse Dumas", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94983, name = "Twilight Mementos", faction = "Alliance", location = "Riverglades", gameVersions = { forever = true } },
                { id = 94997, name = "Lingering Essence", faction = "Alliance", location = "Riverglades", gameVersions = { forever = true } },
                { id = 94998, name = "Curios of Curiosity", npc = "Ashe Amberhall", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94984, name = "Tome of Twilight", npc = "Ashe Amberhall", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94982, name = "Eye of Mugg", npc = "Demar Brant", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94973, name = "Krol'dok Moulding", faction = "Horde", location = "Krol'dok Stronghold, Riverglades", gameVersions = { forever = true } },
                { id = 94974, name = "Key Ingredients", npc = "Kreza Darkthorn", faction = "Horde", gameVersions = { forever = true } },
                { id = 94975, name = "A Token of Vengeance", faction = "Horde", location = "Riverglades", gameVersions = { forever = true } },
                { id = 94972, name = "Tome of Twilight", hint = "The Twilight's Hammer at Krol'dok Stronghold are keeping something written down. Find it.", hintExplorer = "Krol'dok Stronghold holds more than cultists.", faction = "Horde", location = "Riverglades", gameVersions = { forever = true } },
                { id = 94968, name = "Eye of Mugg", npc = "Krom'rosh", faction = "Horde", gameVersions = { forever = true } },
                { id = 94998, name = "Curios of Curiosity", npc = "Ashe Amberhall", faction = "Alliance", optional = true, gameVersions = { forever = true }, recap = "Ashe Amberhall had one more use for the satchel of cult trinkets from Krol'dok: send it across the keep to Melanie Sable, the enchanter. Curios, Ashe called them. I'd have called them evidence. I suppose to an enchanter it's all just material." },
                { id = 96771, name = "Vengeance of the Highborne", npc = "Ranath Nightstride", faction = "Alliance", optional = true, gameVersions = { forever = true }, recap = "Before I went into Krol'dok, Ranath Nightstride in Dalaran gave me a name to look for: Zalfan Moonshadow. Ranath is Highborne, and undead, and called it vengeance. I didn't ask for the history. With the Highborne there's always history, and it's always long. Zalfan didn't come out of Krol'dok." },
                { id = 94969, name = "Krol'dok No More!", npc = "Marcus Tilwell", faction = "Alliance", optional = true, gameVersions = { forever = true }, recap = "Somewhere in Krol'dok I found Marcus Tilwell, who wouldn't explain how any of it had happened and only wanted out. So we left together, me in front. Apparently I wouldn't believe the story anyway. Having seen the place, I'd believe almost anything." },
            },
        },
        {
            chapter = "Word to Stormwind",
            faction = "Alliance",
            summary = "Farholde Keep has been writing to Stormwind for years and hearing nothing back. Time for a different sort of letter: Overlord Kilgar's head, for Bolvar Fordragon in Stormwind Keep. A letter is easy to ignore. A head, less so.",
            recap = "Farholde had been writing to Stormwind for years, and Stormwind had been not writing back. So the knight commander tried a different sort of letter, and I carried the overlord's head to Bolvar Fordragon in Stormwind Keep. Hard to ignore a head.\n\nThen a field marshal's log came my way, and the man who wrote it was still out in the Twilight's Shroud. I found Marshal Ryan dying. He gave me his crest, a warning he never got to finish, and a name. Abigail.\n\nThe knight commander asked me to carry the crest to her in Cathedral Square, and not to expect company. Some faces aren't welcome at some doors, apparently.\n\nI didn't ask why. Some errands you just do.",
            quests = {
                { id = 94894, name = "The Twilight Threat", faction = "Alliance", location = "Farholde Keep, Riverglades", gameVersions = { forever = true } },
                { id = 94885, name = "Field Marshal's Log", faction = "Alliance", location = "Riverglades", gameVersions = { forever = true } },
                { id = 94887, name = "Saving Marshal Ryan", npc = "Demar Brant", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94892, name = "Dying Wish", npc = "Marshal Ryan", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94893, name = "Delivering Closure", npc = "Demar Brant", faction = "Alliance", gameVersions = { forever = true } },
            },
        },
    },
}
